#include "elit21/shopify/webhooks/AppUninstalledWebhookHandler.h"
namespace elit21::shopify::webhooks {AppUninstalledWebhookHandler::AppUninstalledWebhookHandler():platform::BusinessComponent("AppUninstalledWebhookHandler","Persistent Shopify webhook domain handler",platform::BusinessComponentSpec{"shopify","handle_webhook",{},true,false,16U*1024U*1024U}){}AppUninstalledWebhookHandler::AppUninstalledWebhookHandler(Database&database):AppUninstalledWebhookHandler(){database_=&database;}Result<void>AppUninstalledWebhookHandler::handle(const ShopifyWebhook&event){if(!database_)return Result<void>::failure("AppUninstalledWebhookHandler is not bound to Database");return persistWebhookTask(*database_,event,{ShopifyWebhookTopic::app_uninstalled});}platform::OperationResult AppUninstalledWebhookHandler::execute(const platform::OperationContext&context){auto r=executeBusiness(context);r.metrics["database_bound"]=database_?1.0:0.0;r.attributes["handler"]="AppUninstalledWebhookHandler";return r;}}
